  external int len;

  static ffi.Pointer<Buffer> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Uint8> ptr,
    required int cap,
    required int len,
  }) => $allocator<Buffer>()
    ..ref.ptr = ptr
    ..ref.cap = cap
    ..ref.len = len;
}

