typedef TerminalResetFnFunction =
    ffi.Void Function(Terminal terminal, ffi.Pointer<ffi.Void> userdata);
typedef DartGhosttyTerminalResetFnFunction =
    void Function(Terminal terminal, ffi.Pointer<ffi.Void> userdata);

